class AudioSystem{
 constructor(){this.buffers={};this.pending={};this.loops={};this.voices=[];this.currentName='';this.context=null;this.fallback={};this.lastToken=0;try{this.settings={music:.35,engine:.2,effects:.55,mute:false,...JSON.parse(localStorage.getItem(AUDIO_STORAGE)||'{}')}}catch(e){this.settings={music:.35,engine:.2,effects:.55,mute:false}}}
 unlock(){try{if(!this.context){const AC=window.AudioContext||window.webkitAudioContext;if(!AC){this.useFallback=true;if(this.currentName)this.music(this.currentName);return}this.context=new AC();this.gains={};for(const k of ['music','engine','effects']){const g=this.context.createGain();g.connect(this.context.destination);this.gains[k]=g}this.apply()}if(this.context.state==='suspended')this.context.resume().catch(()=>{});if(this.currentName)this.music(this.currentName)}catch(e){this.useFallback=true}}
 buffer(name){if(this.buffers[name])return Promise.resolve(this.buffers[name]);if(!this.pending[name]){const raw=Uint8Array.from(atob(uri(name).split(',')[1]),c=>c.charCodeAt(0));this.pending[name]=this.context.decodeAudioData(raw.buffer).then(b=>{this.buffers[name]=b;return b}).catch(()=>{delete this.pending[name];return null})}return this.pending[name]}
 fallbackPool(name,count=1){if(!this.fallback[name])this.fallback[name]=Array.from({length:count},()=>{const a=new Audio(uri(name));a.preservesPitch=false;return a});return this.fallback[name]}
 loop(key,name,category){if(this.loops[key]||!this.context)return;this.loops[key]={loading:true,name};this.buffer(name).then(buffer=>{const pending=this.loops[key];if(!pending||pending.name!==name||!pending.loading)return;if(!buffer){delete this.loops[key];return}const source=this.context.createBufferSource();source.buffer=buffer;source.loop=true;source.connect(this.gains[category]);if(key==='engine')source.playbackRate.value=.65+C.clamp(this.engineSpeed/23,0,1)*.95;source.start();this.loops[key]={name,source}})}
 stopLoop(key){const loop=this.loops[key];if(loop?.source)try{loop.source.stop()}catch(e){}delete this.loops[key]}
 music(name){this.currentName=name;if(this.useFallback){for(const [n,p] of Object.entries(this.fallback))if(n.startsWith('music_')&&n!==name)p[0].pause();const a=this.fallbackPool(name)[0];a.loop=true;a.volume=this.settings.mute?0:this.settings.music;if(!this.settings.mute)a.play().catch(()=>{});return}if(!this.context)return;if(this.loops.music?.name!==name)this.stopLoop('music');this.loop('music',name,'music');this.apply()}
 pauseMusic(){this.stopLoop('music');for(const [n,p] of Object.entries(this.fallback))if(n.startsWith('music_'))p[0].pause()}
 engineState(on,speed=0){this.engineSpeed=speed;if(this.useFallback){const a=this.fallbackPool('sfx_engine.ogg')[0];a.loop=true;a.volume=this.settings.mute?0:this.settings.engine;a.playbackRate=.65+C.clamp(speed/23,0,1)*.95;if(on&&!this.settings.mute)a.play().catch(()=>{});else a.pause();return}if(!this.context)return;if(on)this.loop('engine','sfx_engine.ogg','engine');else this.stopLoop('engine');if(this.loops.engine?.source)this.loops.engine.source.playbackRate.setTargetAtTime(.65+C.clamp(speed/23,0,1)*.95,this.context.currentTime,.07);this.apply()}
 fx(name,rate=1){if(this.settings.mute)return;if(name==='sfx_pickup.ogg'){const n=performance.now();if(n-this.lastToken<80)return;this.lastToken=n}if(this.useFallback){const pool=this.fallbackPool(name,3),a=pool.find(a=>a.paused||a.ended)||pool[0];a.currentTime=0;a.volume=C.clamp(this.settings.effects,0,1);a.playbackRate=rate;a.play().catch(()=>{});return}if(!this.context)return;this.buffer(name).then(buffer=>{if(!buffer||this.settings.mute||this.context.state!=='running')return;const s=this.context.createBufferSource();s.buffer=buffer;s.playbackRate.value=rate;s.connect(this.gains.effects);if(this.voices.length>=16)try{this.voices.shift().stop()}catch(e){}this.voices.push(s);s.onended=()=>{this.voices=this.voices.filter(x=>x!==s)};s.start()})}
 apply(){if(this.gains)for(const k of ['music','engine','effects'])this.gains[k].gain.setTargetAtTime(this.settings.mute?0:C.clamp(Number(this.settings[k])||0,0,1),this.context.currentTime,.025);for(const [n,p] of Object.entries(this.fallback))for(const a of p)a.volume=this.settings.mute?0:this.settings[n.startsWith('music_')?'music':n==='sfx_engine.ogg'?'engine':'effects']}
 store(){this.apply();try{localStorage.setItem(AUDIO_STORAGE,JSON.stringify(this.settings))}catch(e){}}
}
